import React, { useState, useEffect, useRef } from 'react';
import DashboardLayout from '../components/DashboardLayout';

const forecast = [
  { day: 'Today', icon: '⛅', high: 28, low: 18, rain: 10, humidity: 65, desc: 'Partly Cloudy', wind: 14 },
  { day: 'Tue', icon: '☀️', high: 31, low: 20, rain: 0, humidity: 55, desc: 'Sunny', wind: 10 },
  { day: 'Wed', icon: '🌤', high: 29, low: 19, rain: 5, humidity: 60, desc: 'Mostly Sunny', wind: 12 },
  { day: 'Thu', icon: '🌧️', high: 24, low: 17, rain: 75, humidity: 85, desc: 'Heavy Rain', wind: 22 },
  { day: 'Fri', icon: '⛈️', high: 22, low: 16, rain: 90, humidity: 90, desc: 'Thunderstorm', wind: 35 },
  { day: 'Sat', icon: '🌦️', high: 26, low: 18, rain: 30, humidity: 72, desc: 'Light Rain', wind: 16 },
  { day: 'Sun', icon: '☀️', high: 30, low: 20, rain: 0, humidity: 50, desc: 'Clear Sky', wind: 8 },
];

const ALERTS = [
  { type: 'danger', icon: '⛈️', title: 'Thunderstorm Warning', severity: 'High', day: 'Friday', color: 'border-red-700/40 bg-red-900/10 text-red-400',
    actions: ['Secure farm equipment in shed', 'Avoid field work Friday afternoon', 'Check drainage channels', 'Harvest any ripe crops by Thursday'] },
  { type: 'warning', icon: '🌧️', title: 'Heavy Rainfall Alert', severity: 'Medium', day: 'Thursday', color: 'border-yellow-700/40 bg-yellow-900/10 text-yellow-400',
    actions: ['Avoid irrigation — natural rain sufficient', 'Protect crops from waterlogging', 'Apply fungicide preventively', 'Ensure field drainage is clear'] },
  { type: 'info', icon: '☀️', title: 'Heatwave Advisory', severity: 'Low', day: 'Tuesday', color: 'border-orange-700/40 bg-orange-900/10 text-orange-400',
    actions: ['Irrigate early morning (5–7 AM)', 'Avoid pesticide spray in peak heat', 'Mulch soil to retain moisture', 'Monitor crop wilting signs'] },
  { type: 'success', icon: '🌱', title: 'Optimal Sowing Window', severity: 'Info', day: 'Tue–Wed', color: 'border-green-700/40 bg-green-900/10 text-green-400',
    actions: ['Ideal for wheat sowing', 'Low humidity, good temperature', 'Soil moisture at optimal level', 'Apply basal fertilizer before sowing'] },
];

const hourly = [
  { time: '6AM', temp: 22, icon: '🌅', rain: 0 }, { time: '9AM', temp: 25, icon: '☀️', rain: 0 },
  { time: '12PM', temp: 28, icon: '☀️', rain: 5 }, { time: '3PM', temp: 30, icon: '🌤', rain: 10 },
  { time: '6PM', temp: 27, icon: '⛅', rain: 15 }, { time: '9PM', temp: 23, icon: '🌙', rain: 5 },
];

function TempChart() {
  const canvasRef = useRef();
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !window.Chart) return;
    const existing = window.Chart.getChart(canvas);
    if (existing) existing.destroy();
    new window.Chart(canvas, {
      type: 'line',
      data: {
        labels: forecast.map(f => f.day),
        datasets: [
          { label: 'High °C', data: forecast.map(f => f.high), borderColor: '#f97316', backgroundColor: '#f9731620', borderWidth: 2, fill: false, tension: 0.4, pointRadius: 4, pointBackgroundColor: '#f97316' },
          { label: 'Low °C', data: forecast.map(f => f.low), borderColor: '#38bdf8', backgroundColor: '#38bdf820', borderWidth: 2, fill: false, tension: 0.4, pointRadius: 4, pointBackgroundColor: '#38bdf8' },
          { label: 'Rain %', data: forecast.map(f => f.rain), borderColor: '#22c55e', backgroundColor: '#22c55e15', borderWidth: 2, fill: true, tension: 0.4, pointRadius: 3, yAxisID: 'y1' },
        ]
      },
      options: {
        responsive: true, maintainAspectRatio: false,
        plugins: { legend: { labels: { color: '#9ca3af', font: { size: 10 } } }, tooltip: { backgroundColor: '#0a1a0f' } },
        scales: {
          x: { grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#6b7280', font: { size: 10 } } },
          y: { grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#6b7280', font: { size: 10 }, callback: v => v + '°' }, position: 'left' },
          y1: { grid: { display: false }, ticks: { color: '#6b7280', font: { size: 10 }, callback: v => v + '%' }, position: 'right' }
        }
      }
    });
  }, []);
  return <div className="h-52"><canvas ref={canvasRef} /></div>;
}

export default function WeatherPage() {
  const [unit, setUnit] = useState('C');
  const [activeAlert, setActiveAlert] = useState(0);
  const convert = t => unit === 'C' ? t : Math.round(t * 9 / 5 + 32);
  const maxTemp = Math.max(...forecast.map(f => f.high));

  return (
    <DashboardLayout title="Weather Alert System" subtitle="Real-time hyperlocal weather intelligence & smart farm alerts">

      {/* Current Weather */}
      <div className="glass rounded-2xl p-6 mb-5 border border-green-900/30 relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-blue-500/5 rounded-full blur-3xl pointer-events-none" />
        <div className="relative z-10 flex flex-col md:flex-row items-start md:items-center justify-between gap-6">
          <div className="flex items-center gap-4">
            <span className="text-6xl">⛅</span>
            <div>
              <div className="font-display font-black text-6xl text-white">{convert(28)}°{unit}</div>
              <div className="text-gray-400 text-sm">Partly Cloudy · Feels like {convert(26)}°</div>
              <div className="flex items-center gap-2 mt-2">
                <span className="text-green-400 text-xs">📍 Your Farm · Maharashtra</span>
                <span className="text-gray-600 text-xs">· Updated 2 min ago</span>
              </div>
            </div>
          </div>
          <div className="grid grid-cols-3 gap-3">
            {[{ icon: '💧', l: 'Humidity', v: '65%' }, { icon: '💨', l: 'Wind', v: '14 km/h' }, { icon: '👁️', l: 'Visibility', v: '10 km' }, { icon: '🌡️', l: 'Dew Point', v: '18°C' }, { icon: '🌊', l: 'Pressure', v: '1013 hPa' }, { icon: '☀️', l: 'UV Index', v: '6.2' }].map(i => (
              <div key={i.l} className="glass-dark rounded-xl p-2.5 text-center">
                <div className="text-lg mb-0.5">{i.icon}</div>
                <div className="text-white font-semibold text-xs">{i.v}</div>
                <div className="text-gray-600 text-xs">{i.l}</div>
              </div>
            ))}
          </div>
          <button onClick={() => setUnit(u => u === 'C' ? 'F' : 'C')}
            className="glass-green border border-green-700/40 text-green-300 px-4 py-2 rounded-xl text-sm font-medium hover:bg-green-900/30 transition-all self-start">
            °{unit === 'C' ? 'F' : 'C'}
          </button>
        </div>
      </div>

      {/* Hourly */}
      <div className="glass rounded-2xl p-5 mb-5 border border-green-900/30">
        <h3 className="font-display font-semibold text-white text-sm mb-4">⏰ Hourly Forecast</h3>
        <div className="flex gap-3 overflow-x-auto pb-2">
          {hourly.map((h, i) => (
            <div key={i} className={`flex-shrink-0 glass-dark rounded-2xl p-4 text-center min-w-[80px] ${i === 2 ? 'border border-green-500/40 bg-green-900/10' : ''}`}>
              <div className="text-gray-400 text-xs mb-2">{h.time}</div>
              <div className="text-2xl mb-2">{h.icon}</div>
              <div className="text-white font-bold text-sm">{convert(h.temp)}°</div>
              {h.rain > 0 && <div className="text-blue-400 text-xs mt-1">💧{h.rain}%</div>}
            </div>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-5 mb-5">
        {/* 7-Day Chart */}
        <div className="glass rounded-2xl p-5 border border-green-900/30">
          <h3 className="font-display font-semibold text-white text-sm mb-4">📊 7-Day Temperature & Rain Chart</h3>
          <TempChart />
        </div>

        {/* 7-Day List */}
        <div className="glass rounded-2xl p-5 border border-green-900/30">
          <h3 className="font-display font-semibold text-white text-sm mb-4">📅 7-Day Forecast</h3>
          <div className="space-y-2">
            {forecast.map((f, i) => (
              <div key={i} className={`flex items-center gap-3 p-2.5 rounded-xl transition-all hover:bg-white/5 ${i === 0 ? 'bg-green-900/20 border border-green-800/30' : ''}`}>
                <div className="w-10 text-gray-400 text-xs font-medium">{f.day}</div>
                <div className="text-xl w-7">{f.icon}</div>
                <div className="flex-1 text-gray-300 text-xs hidden sm:block">{f.desc}</div>
                <div className="text-blue-400 text-xs w-8">{f.rain}%</div>
                <div className="flex items-center gap-1.5 text-xs">
                  <span className="text-blue-300">{convert(f.low)}°</span>
                  <div className="w-12 h-1.5 bg-black/40 rounded-full overflow-hidden">
                    <div className="h-full bg-gradient-to-r from-blue-500 to-orange-400 rounded-full" style={{ width: `${(f.high / maxTemp) * 100}%` }} />
                  </div>
                  <span className="text-orange-300">{convert(f.high)}°</span>
                </div>
                {f.wind > 25 && <span className="text-red-400 text-xs">💨{f.wind}</span>}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Smart Alerts */}
      <div>
        <h3 className="font-display font-semibold text-white mb-4">🔔 Smart Farm Alert System</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {ALERTS.map((a, i) => (
            <div key={i} className={`glass rounded-2xl border ${a.color} overflow-hidden cursor-pointer transition-all ${activeAlert === i ? 'ring-1 ring-green-500/40' : ''}`}
              onClick={() => setActiveAlert(activeAlert === i ? -1 : i)}>
              <div className="p-4 flex items-start gap-3">
                <span className="text-2xl flex-shrink-0">{a.icon}</span>
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-1">
                    <span className="text-white font-semibold text-sm">{a.title}</span>
                    <span className={`text-xs px-2 py-0.5 rounded-full border ${a.color}`}>{a.severity}</span>
                  </div>
                  <div className="text-gray-400 text-xs">{a.day}</div>
                </div>
                <span className="text-gray-500 text-sm">{activeAlert === i ? '▲' : '▼'}</span>
              </div>
              {activeAlert === i && (
                <div className="px-4 pb-4 border-t border-white/5 pt-3 animate-fade-in">
                  <div className="text-gray-400 text-xs mb-2 font-semibold uppercase tracking-wider">Preventive Actions</div>
                  <div className="space-y-1.5">
                    {a.actions.map((action, j) => (
                      <div key={j} className="flex items-start gap-2">
                        <span className="text-green-400 text-xs mt-0.5">✓</span>
                        <span className="text-gray-300 text-xs">{action}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </DashboardLayout>
  );
}
